CREATE TABLE IF NOT EXISTS TopShelfDeveloper.TopShelfOSAccess ( EmployeeID INT NOT NULL PRIMARY KEY, CognitoSub VARCHAR(64) NOT NULL, Email VARCHAR(254) NOT NULL, CreatedAt TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, UpdatedAt TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, UpdatedBy VARCHAR(64) NOT NULL, UNIQUE KEY CognitoSub (CognitoSub), CONSTRAINT FK_TopShelfOSAccess_Employees FOREIGN KEY (EmployeeID) REFERENCES TopShelfDeveloper.Employees (ID) ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;;
